def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each either integer or one of '+', '-', '*', '/'.
    Division truncates toward zero.
    """
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division
                # Python division truncates toward zero when using int()
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

