code:
def solve(grid):
    """Count islands in a binary matrix.

    An *island* is a group of horizontally or vertically adjacent cells containing 1.
    The function mutates the input grid to mark visited cells (setting them to 0)
    and performs a depth‑first search for each unvisited land cell.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    islands = 0
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if 0 <= i < rows and 0 <= j < cols and grid[i][j] == 1:
                grid[i][j] = 0
                stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                islands += 1
                dfs(i, j)
    return islands

