def solve(grid):
    """Count islands in a possibly jagged binary grid.
    Connectivity is 4-directional (up, down, left, right).
    Rows may have different lengths; cells outside a row's length are treated as absent.
    """
    if not grid:
        return 0
    rows = len(grid)
    # visited mirrors the shape of grid
    visited = [ [False]*len(row) for row in grid ]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            # neighbors: up, down, left, right
            # up
            if i-1 >= 0 and j < len(grid[i-1]) and not visited[i-1][j] and grid[i-1][j] == 1:
                stack.append((i-1, j))
            # down
            if i+1 < rows and j < len(grid[i+1]) and not visited[i+1][j] and grid[i+1][j] == 1:
                stack.append((i+1, j))
            # left
            if j-1 >= 0 and not visited[i][j-1] and grid[i][j-1] == 1:
                stack.append((i, j-1))
            # right
            if j+1 < len(grid[i]) and not visited[i][j+1] and grid[i][j+1] == 1:
                stack.append((i, j+1))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

