    def __eq__(self, other):
        # Normalize both self and other to list of [char, count] pairs
        def normalize(seq):
            result = []
            for item in seq:
                # Accept tuple, list, or custom object with two attributes
                try:
                    ch, cnt = item[0], item[1]
                except Exception:
                    # Fallback: if object has attributes
                    try:
                        ch, cnt = item.ch, item.cnt
                    except Exception:
                        return None
                result.append([ch, cnt])
            return result
