import bisect

def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Accepts any iterable of integers; returns 0 for non-iterable inputs.
    """
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    tails = []
    for x in iterator:
        # Ensure x is comparable; if not, skip
        try:
            idx = bisect.bisect_left(tails, x)
        except TypeError:
            continue
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

