def solve(word1: str, word2: str) -> int:
    """Compute the Levenshtein edit distance between two strings.
    Allows insertions, deletions, and substitutions with unit cost.
    If inputs are not strings, treat them as empty strings.
    """
    if not isinstance(word1, str):
        word1 = ''
    if not isinstance(word2, str):
        word2 = ''
    m, n = len(word1), len(word2)
    # DP row previous
    prev = list(range(n+1))
    for i in range(1, m+1):
        cur = [i] + [0]*n
        for j in range(1, n+1):
            if word1[i-1] == word2[j-1]:
                cur[j] = prev[j-1]
            else:
                cur[j] = 1 + min(prev[j], cur[j-1], prev[j-1])
        prev = cur
    return prev[n]

