def solve(grid):
    """Count islands in a binary matrix without mutating the input.

    An island is a group of horizontally or vertically adjacent cells containing 1.
    The algorithm uses an explicit stack for depth‑first search and a separate
    ``visited`` set to avoid modifying the original ``grid``.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = set()
    islands = 0
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            if 0 <= i < rows and 0 <= j < cols and grid[i][j] == 1:
                visited.add((i, j))
                stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and (i, j) not in visited:
                islands += 1
                dfs(i, j)
    return islands

